# Builds research/network-risk/cycles/006/theme-token-triggers.research.json from the raw files of this work directory.
import json, os, glob, gzip, collections
HERE = os.path.dirname(os.path.abspath(__file__))
RAW = os.path.join(HERE, 'raw')
def jz(fn): return json.load(gzip.open(fn, 'rt'))
S = json.load(open(os.path.join(RAW, 'stats.json')))
NETS = json.load(open(os.path.join(HERE, '..', '..', '..', 'state', 'networks.json')))['networks']
ALL = [n['chainId'] for n in NETS]
NAME = {n['chainId']: n['name'] for n in NETS}
def tot(k, sub=None):
    return sum(((o.get(sub) or {}).get(k) or 0) if sub else (o.get(k) or 0) for o in S.values())
C = collections.Counter()
for f in glob.glob(os.path.join(RAW, 'sweepC_*.json.gz')):
    d = jz(f)['tokens']; C['tok'] += len(d); C['trials'] += sum(o['trials'] for o in d.values()); C['ok'] += sum(o['ok'] for o in d.values())
targets = tot('targets'); over10k = tot('over10k')
tA = tot('trials', 'sweepA'); aA = tot('accepted', 'sweepA'); tB = tot('trials', 'sweepB'); aB = tot('accepted', 'sweepB'); nB = tot('tokens', 'sweepB')
fA = tot('failedCalls', 'sweepA'); fB = tot('failedCalls', 'sweepB')
unnamed = tot('unnamed'); related = tot('related')
per = '; '.join('%s %d (%d above 10,000 USD)' % (NAME[int(c)], o['targets'], o.get('over10k') or 0) for c, o in S.items())
step3 = json.load(open(os.path.join(RAW, 'step3_list.json')))
fam3 = len({x['fam'] for x in step3})
W = 'research/network-risk/cycles/006/theme-token-triggers.work/'
SRC = lambda cid, a: 'https://sourcify.dev/server/v2/contract/%d/%s?fields=sources,compilation,proxyResolution' % (cid, a)
PM_REFS = ['src/PoolManager.sol:279-288', 'src/PoolManager.sol:291-297', 'src/PoolManager.sol:349-365', 'src/types/Currency.sol:60-95']

